<template>
<el-dialog :model-value="modelValue" :title="kind==='image'?'模特试衣':'PPT 提案导出'" width="94%" :close-on-click-modal="false" @update:model-value="$emit('update:modelValue',$event)">
<el-alert v-if="error" :title="error" type="error" :closable="false" class="space"/>
<el-alert title="关闭弹窗保留配置和后台任务，不会取消生成。" type="info" :closable="false" class="space"/>
<template v-if="kind==='image'">
<el-alert v-if="!providerAvailable" :title="blockedReason||'正在检查试衣服务状态'" type="warning" :closable="false" class="space"/>
<div class="tool-grid"><section><h3>本次试衣</h3><el-form label-position="top"><el-form-item label="方案范围"><el-select v-model="targetIds" multiple filterable placeholder="选择当前页已选方案" style="width:100%"><el-option v-for="id in combinationIds" :key="id" :value="id" :label="id"/></el-select></el-form-item><el-form-item label="模特照片"><input type="file" accept="image/png,image/jpeg,image/webp" aria-label="上传模特照片" @change="uploadModel"/></el-form-item><el-image v-if="modelPreview" :src="modelPreview" fit="contain" class="model-preview"/><el-checkbox v-model="modelAuthorized">我有权使用这张模特照片生成试衣图</el-checkbox><p>已选 {{targetIds.length}} 套，每套生成一项任务。请先在方案详情指定各件商品的颜色。</p><el-button type="primary" :loading="busy" :disabled="!providerAvailable||!model||!modelAuthorized||!targetIds.length" @click="generateImages">生成模特图</el-button></el-form></section>
<section><div class="actions"><h3>任务与逐图复核</h3><el-button :loading="refreshing" @click="refreshTasks">刷新状态</el-button></div><el-empty v-if="!tasks.length" description="尚无试衣任务"/><el-card v-for="task in tasks" :key="task.id" class="space"><template #header><strong>{{task.combinationId}}</strong> <el-tag>{{statusLabel(task.status)}}</el-tag> <el-tag v-if="task.stale" type="danger">素材已变化，结果过期</el-tag></template><p v-if="task.errorMessage">{{task.errorMessage}}</p><div class="actions"><el-button v-if="['queued','running','unknown','cancel_requested'].includes(task.status)" @click="queryTask(task.id)">查询任务</el-button><el-button v-if="['queued','running','unknown'].includes(task.status)" @click="cancelTask(task)">请求取消</el-button><el-button v-if="['failed','cancelled','rejected'].includes(task.status)" :disabled="!model||!providerAvailable||!modelAuthorized" @click="retryTask(task)">重新生成</el-button></div><div v-for="(result,i) in task.results" :key="i" class="result"><template v-if="result.status==='success'"><el-image v-if="resultUrls[`${task.id}:${i}`]" :src="resultUrls[`${task.id}:${i}`]" :preview-src-list="[resultUrls[`${task.id}:${i}`]]" fit="contain" class="result-image"/><el-button v-else @click="loadResult(task.id,i)">查看结果图 {{i+1}}</el-button><el-button :disabled="task.stale" @click="openReview(task,i)">复核此图</el-button></template><span v-else>结果 {{i+1}}：{{result.status||'尚未返回'}}</span></div></el-card></section></div>
</template>
<template v-else>
<el-form label-width="120px"><el-form-item label="导出范围"><el-radio-group v-model="exportScope"><el-radio value="page">当前页已选 {{combinationIds.length}} 套</el-radio><el-radio value="all" :disabled="selectedCount>100">全部已选 {{selectedCount}} 套</el-radio></el-radio-group></el-form-item><el-alert v-if="selectedCount>100" title="单文件最多 100 套，请在已选方案分页后逐页导出，不会自动截断。" type="warning" :closable="false" class="space"/><el-form-item label="价格展示"><el-select v-model="priceMode"><el-option label="不展示价格" value="none"/><el-option label="团购价" value="group"/><el-option label="VIP 价" value="vip"/></el-select></el-form-item><el-form-item label="图片布局"><el-radio-group v-model="imageMode"><el-radio value="original">商品原图</el-radio><el-radio value="model">已采用模特图＋商品原图</el-radio></el-radio-group></el-form-item></el-form>
<el-card class="space"><template #header>输出内容</template><p>按已选方案顺序输出，包含商品名称、主 SKU、品号、货号、图片及所选价格口径，文字可编辑。</p><p>范围：{{exportScope==='all'?selectedCount:combinationIds.length}} 套。未核对的模特图不会进入文件。</p></el-card>
<el-alert v-for="issue in preflight?.issues||[]" :key="issue" :title="issue" type="error" :closable="false" class="space"/><el-alert v-if="preflight?.ready" :title="`检查通过，可生成 ${preflight.combinationCount} 套方案的 PPTX`" type="success" :closable="false" class="space"/>
<div class="actions"><el-button :loading="busy" @click="checkExport">检查导出内容</el-button><el-button type="primary" :loading="busy" :disabled="!preflight?.ready" @click="exportPpt">生成并下载 PPTX</el-button></div>
</template>
<template #footer><el-button @click="$emit('update:modelValue',false)">关闭，返回已选方案</el-button></template>
<el-dialog v-model="reviewVisible" title="复核模特图" width="560px" append-to-body><el-image v-if="reviewTask&&resultUrls[`${reviewTask.id}:${resultNo}`]" :src="resultUrls[`${reviewTask.id}:${resultNo}`]" fit="contain" class="model-preview"/><el-checkbox v-for="(label,key) in checkLabels" :key="key" v-model="checks[key]">{{label}}</el-checkbox><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" placeholder="不采用时请说明原因" class="space"/><template #footer><el-button :loading="busy" @click="review(false)">不采用</el-button><el-button type="primary" :loading="busy" :disabled="!Object.values(checks).every(Boolean)" @click="review(true)">确认采用</el-button></template></el-dialog>
</el-dialog>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {fashionRequest} from '@/api/fashion/client'
import type {RuoYiResult} from '@/api/fashion/types'
interface ImageTask {id:string;status:string;rowVersion:number;draftVersion:number;combinationId:string;stale:boolean;errorMessage?:string;results:{status:string}[]}
interface Preflight {ready:boolean;issues:string[];combinationCount:number;maxPerFile:number}
const props=defineProps<{modelValue:boolean;kind:'image'|'ppt';poolId:string;rowVersion:number;selectedCount:number;combinationIds:string[]}>()
defineEmits<{'update:modelValue':[boolean]}>()
const base=computed(()=>`pools/${props.poolId}/proposal`),busy=ref(false),refreshing=ref(false),error=ref(''),providerAvailable=ref(false),blockedReason=ref(''),tasks=ref<ImageTask[]>([]),model=ref<{objectKey:string;sha256:string}>(),modelPreview=ref(''),modelAuthorized=ref(false),targetIds=ref<string[]>([]),resultUrls=reactive<Record<string,string>>({})
const exportScope=ref<'page'|'all'>('page'),priceMode=ref('none'),imageMode=ref('original'),preflight=ref<Preflight>(),reviewVisible=ref(false),reviewTask=ref<ImageTask>(),resultNo=ref(0),reason=ref(''),checks=reactive({style:false,color:false,completeness:false,quality:false}),checkLabels={style:'款式正确',color:'颜色正确',completeness:'商品齐全',quality:'无明显变形'}
const requestKeys=new Map<string,string>()
let timer:ReturnType<typeof setTimeout>|undefined
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function refreshTasks(){refreshing.value=true;try{const {data}=await fashionRequest<RuoYiResult<{providerAvailable:boolean;blockedReason:string;tasks:ImageTask[]}>>({path:`${base.value}/images`,params:{rowVersion:props.rowVersion}});providerAvailable.value=data.providerAvailable;blockedReason.value=data.blockedReason;tasks.value=data.tasks}catch(e){error.value=e instanceof Error?e.message:'任务读取失败'}finally{refreshing.value=false}}
async function queryTask(id:string){await action(async()=>{const {data}=await fashionRequest<RuoYiResult<ImageTask>>({path:`${base.value}/images/${id}`});tasks.value=tasks.value.map(t=>t.id===id?data:t)})}
async function uploadModel(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){ElMessage.warning('请上传不超过 10 MB 的 PNG、JPEG 或 WebP 图片');return}await action(async()=>{const data=new FormData();data.append('file',file);model.value=(await fashionRequest<RuoYiResult<{objectKey:string;sha256:string}>>({path:`${base.value}/models`,method:'post',params:{rowVersion:props.rowVersion},body:data})).data;if(modelPreview.value)URL.revokeObjectURL(modelPreview.value);modelPreview.value=URL.createObjectURL(file);modelAuthorized.value=false})}
async function submitImage(combinationId:string,newAttempt=false){const identity=[props.poolId,props.rowVersion,combinationId,model.value?.sha256].join(':');let requestKey=requestKeys.get(identity);if(!requestKey||newAttempt){requestKey=crypto.randomUUID();requestKeys.set(identity,requestKey)}const task=(await fashionRequest<RuoYiResult<ImageTask>>({path:`${base.value}/images`,method:'post',body:{rowVersion:props.rowVersion,combinationId,model:model.value,requestKey},timeoutMs:120000})).data;tasks.value=[task,...tasks.value.filter(t=>t.id!==task.id)]}
async function generateImages(){await action(async()=>{for(const id of targetIds.value)await submitImage(id);ElMessage.success('试衣任务已提交')})}
async function retryTask(task:ImageTask){await action(()=>submitImage(task.combinationId,true))}
async function cancelTask(task:ImageTask){await action(async()=>{const {data}=await fashionRequest<RuoYiResult<ImageTask>>({path:`${base.value}/images/${task.id}/cancel`,method:'post',body:{rowVersion:task.rowVersion}});tasks.value=tasks.value.map(t=>t.id===task.id?data:t)})}
async function loadResult(id:string,no:number){await action(async()=>{const blob=await fashionRequest<Blob>({path:`${base.value}/images/${id}/results/${no}`,responseType:'blob'});if(!blob.type.startsWith('image/'))throw new Error('服务未返回图片');const key=`${id}:${no}`;if(resultUrls[key])URL.revokeObjectURL(resultUrls[key]);resultUrls[key]=URL.createObjectURL(blob)})}
function openReview(task:ImageTask,no:number){reviewTask.value=task;resultNo.value=no;reason.value='';Object.assign(checks,{style:false,color:false,completeness:false,quality:false});reviewVisible.value=true;loadResult(task.id,no)}
async function review(adopt:boolean){if(!reviewTask.value)return;if(!adopt&&!reason.value.trim())return ElMessage.warning('请填写不采用原因');await action(async()=>{const task=reviewTask.value!;const {data}=await fashionRequest<RuoYiResult<ImageTask>>({path:`${base.value}/images/${task.id}/review`,method:'post',body:{rowVersion:task.rowVersion,resultNo:resultNo.value,adopt,checks,reason:reason.value}});tasks.value=tasks.value.map(t=>t.id===task.id?data:t);reviewVisible.value=false;preflight.value=undefined})}
function exportBody(){const adoptedTaskIds:Record<string,string>={};for(const task of tasks.value)if(task.status==='adopted'&&!task.stale&&!adoptedTaskIds[task.combinationId])adoptedTaskIds[task.combinationId]=task.id;return{rowVersion:props.rowVersion,combinationIds:exportScope.value==='all'?[]:props.combinationIds,priceMode:priceMode.value,imageMode:imageMode.value,adoptedTaskIds}}
async function checkExport(){await action(async()=>{if(exportScope.value==='page'&&!props.combinationIds.length)throw new Error('当前页没有已选方案');preflight.value=(await fashionRequest<RuoYiResult<Preflight>>({path:`${base.value}/preflight`,method:'post',body:exportBody()})).data})}
async function exportPpt(){await action(async()=>{const blob=await fashionRequest<Blob>({path:`${base.value}/pptx`,method:'post',body:exportBody(),responseType:'blob',timeoutMs:120000});const mime=blob.type.split(';')[0].toLowerCase();const head=new Uint8Array(await blob.slice(0,4).arrayBuffer());if(!['application/vnd.openxmlformats-officedocument.presentationml.presentation','application/zip','application/x-zip-compressed'].includes(mime)||head[0]!==0x50||head[1]!==0x4b||head[2]!==0x03||head[3]!==0x04){let message='服务未返回有效的 PPTX 文件，请重试或检查导出条件';if(mime==='application/json'){try{message=JSON.parse(await blob.text()).msg||message}catch{}}throw new Error(message)}const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`套装提案-${props.poolId}.pptx`;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);ElMessage.success('PPTX 已生成并开始下载')})}
watch([exportScope,priceMode,imageMode,()=>props.rowVersion,()=>props.combinationIds.join(',')],()=>preflight.value=undefined)
watch(()=>props.modelValue,async visible=>{clearTimeout(timer);if(visible){await refreshTasks();poll()}})
function poll(){clearTimeout(timer);if(!props.modelValue)return;timer=setTimeout(async()=>{for(const task of tasks.value.filter(t=>['queued','running','cancel_requested'].includes(t.status)))await queryTask(task.id);poll()},5000)}
watch(()=>props.poolId,()=>{tasks.value=[];model.value=undefined;targetIds.value=[];preflight.value=undefined;modelAuthorized.value=false;clearUrls()})
function clearUrls(){if(modelPreview.value)URL.revokeObjectURL(modelPreview.value);modelPreview.value='';for(const key of Object.keys(resultUrls)){URL.revokeObjectURL(resultUrls[key]);delete resultUrls[key]}}
onBeforeUnmount(()=>{clearTimeout(timer);clearUrls()})
function statusLabel(status:string){return ({queued:'排队中',running:'生成中',unknown:'状态待确认',review:'待复核',adopted:'已采用',rejected:'未采用',failed:'失败',cancel_requested:'已请求取消',cancelled:'已取消'} as Record<string,string>)[status]||status}
</script>
<style scoped>.space{margin:12px 0}.tool-grid{display:grid;grid-template-columns:minmax(250px,1fr) minmax(400px,2fr);gap:24px}.model-preview{width:100%;height:220px;margin-bottom:12px}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.result{display:flex;align-items:center;gap:12px;margin:12px 0}.result-image{width:220px;height:240px}@media(max-width:800px){.tool-grid{grid-template-columns:1fr}}</style>
